import React, { useState, useEffect } from 'react';
import MetricsPanel from './MetricsPanel';
import ChartsPanel from './ChartsPanel';
import AlertsPanel from './AlertsPanel';
import MultiLocationPanel from './MultiLocationPanel';
import AIIntelligence from './AIIntelligence';
import './Dashboard.css';

function Dashboard({ metrics, suggestions, isConnected }) {
  const [alerts, setAlerts] = useState([]);
  const [historicalData, setHistoricalData] = useState([]);
  const [optimizedMetrics, setOptimizedMetrics] = useState(null);
  const [settings, setSettings] = useState({
    energyCostPerKwh: 0.12,
    carbonTarget: 300,
    alertThreshold: 600
  });

  const handleSettingsChange = (newSettings) => {
    setSettings(newSettings);
    // In a real app, this would update the backend calculations
  };

  const handleOptimizationApplied = (newMetrics) => {
    setOptimizedMetrics(newMetrics);
    // In a real app, this would trigger backend optimization
  };

  // Use optimized metrics if available, otherwise use current metrics
  const currentMetrics = optimizedMetrics || metrics;

  useEffect(() => {
    // Generate alerts based on metrics
    const newAlerts = [];
    
    if (currentMetrics.total_consumption > 600) {
      newAlerts.push({
        id: Date.now(),
        type: 'warning',
        message: `High energy consumption detected: ${currentMetrics.total_consumption} kWh`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
    
    if (currentMetrics.carbon_emissions > 300) {
      newAlerts.push({
        id: Date.now() + 1,
        type: 'critical',
        message: `Carbon emissions exceed target: ${currentMetrics.carbon_emissions} kg CO2`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
    
    if (currentMetrics.efficiency_score < 50) {
      newAlerts.push({
        id: Date.now() + 2,
        type: 'info',
        message: `Energy efficiency below optimal: ${currentMetrics.efficiency_score}%`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
    
    setAlerts(prev => [...newAlerts, ...prev].slice(0, 10));
  }, [currentMetrics]);

  useEffect(() => {
    // Update historical data for charts
    setHistoricalData(prev => {
      const newData = [...prev, {
        timestamp: new Date(),
        consumption: currentMetrics.total_consumption,
        emissions: parseFloat(currentMetrics.carbon_emissions),
        cost: parseFloat(currentMetrics.cost_per_hour)
      }];
      return newData.slice(-50); // Keep last 50 data points
    });
  }, [currentMetrics]);

  return (
    <div className="dashboard">
      {/* AI Intelligence System - The main focus */}
      <div className="panel-row ai-intelligence-section">
        <AIIntelligence 
          metrics={metrics} 
          onOptimizationApplied={handleOptimizationApplied}
        />
      </div>
      
      <div className="dashboard-grid">
        {/* Core metrics and alerts - essential info */}
        <div className="panel-row main-metrics">
          <MetricsPanel metrics={currentMetrics} isConnected={isConnected} />
          <AlertsPanel alerts={alerts} />
        </div>
        
        {/* Charts for visual data - keep it simple */}
        <div className="panel-row charts-section">
          <ChartsPanel 
            historicalData={historicalData} 
            currentMetrics={currentMetrics}
          />
        </div>
        
        {/* Enterprise view - business value */}
        <div className="panel-row enterprise-section">
          <MultiLocationPanel currentMetrics={currentMetrics} />
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
